const people=['Ana Martins','Bruno Almeida','Carla Santos'];
// Fixed presentation fixtures: no customer data, requests or database writes.
export const reportFixtures=people.flatMap((person,p)=>Array.from({length:12},(_,i)=>({person,day:1+i%12,chats:1,answered:i!==11,firstReply:35+(i*29+p*17)%220,duration:240+i*37+p*30,human:i<(9-p*2),transferred:i<3,closed:i<9,call:i<8,callAnswered:i<6,abandoned:i===6,callDuration:180+i*43+p*21,wait:12+i*8+p*4,csat:i<5?([5,4,5,3,5][(i+p)%5]):null,nps:i<5?([10,9,8,6,9][(i+p)%5]):null})));
export function reportData(days=30,person='all'){
 const rows=reportFixtures.filter(r=>r.day<=days&&(person==='all'||r.person===person)),chats=rows.filter(r=>r.answered),calls=rows.filter(r=>r.call),answered=calls.filter(r=>r.callAnswered),surveys=answered.filter(r=>r.csat!==null),promoters=surveys.filter(r=>r.nps>=9).length,detractors=surveys.filter(r=>r.nps<=6).length;
 const avg=(a,k)=>a.length?a.reduce((n,r)=>n+r[k],0)/a.length:0;
 return {rows,chats,calls,answered,surveys,promoters,detractors,passives:surveys.length-promoters-detractors,satisfied:surveys.filter(r=>r.csat>=4).length,sla:chats.filter(r=>r.firstReply<=120).length,tma:avg(chats,'duration'),tme:avg(chats,'firstReply'),callTma:avg(answered,'callDuration'),callTme:avg(answered,'wait')};
}
const pct=(n,d)=>d?Math.round(n/d*100):0;
const time=n=>`${Math.floor(Math.round(n)/60)}m ${String(Math.round(n)%60).padStart(2,'0')}s`;
const kpi=(label,value,note)=>`<article class="rp-kpi"><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`;
function bars(items){const max=Math.max(1,...items.map(x=>x[1]));return `<div class="rp-bars">${items.map(([name,n,color])=>`<div><span>${name}</span><i><b style="width:${n/max*100}%;background:${color||'#6264d8'}"></b></i><strong>${n}</strong></div>`).join('')}</div>`}
export function mountReports(root){let tab='chats',days=30,person='all';function draw(){const d=reportData(days,person),calls=tab==='calls',n=calls?d.calls.length:d.rows.length,answered=calls?d.answered.length:d.chats.length,sla=pct(d.sla,d.chats.length),csat=pct(d.satisfied,d.surveys.length),nps=d.surveys.length?Math.round((d.promoters-d.detractors)/d.surveys.length*100):0;
 root.innerHTML=`<section class="rp"><div class="rp-notice"><span>DEMONSTRAÇÃO</span><div><strong>Dados ilustrativos — não são indicadores reais da operação.</strong><p>Cenário fictício inspirado nas 36 oportunidades de Ana, Bruno e Carla. Chamadas e pesquisas de satisfação não estão integradas. Nenhum dado é gravado no banco.</p></div></div><div class="rp-toolbar"><div class="rp-tabs" aria-label="Tipo de relatório"><button data-tab="chats" aria-pressed="${!calls}">Chats</button><button data-tab="calls" aria-pressed="${calls}">Chamadas e experiência</button></div><label>Período ilustrativo<select id="rp-days"><option value="7" ${days===7?'selected':''}>Últimos 7 dias</option><option value="30" ${days===30?'selected':''}>Últimos 30 dias</option></select></label><label>Equipe de demonstração<select id="rp-person"><option value="all">Toda a equipe fictícia</option>${people.map(p=>`<option ${person===p?'selected':''}>${p}</option>`).join('')}</select></label></div><div class="rp-title"><div><h2>${calls?'Experiência em cada ligação':'Eficiência em cada conversa'}</h2><p>${calls?'Volume, atendimento e percepção do cliente.':'Tempo de resposta, distribuição e resolução.'}</p></div><span>Referência fixa: 28/09/2026<br>${days} dias · ${n} ${calls?'chamadas fictícias':'chats fictícios'}</span></div><div class="rp-kpis">${calls?kpi('Chamadas recebidas',n,'Total do recorte')+kpi('Atendidas',answered,`${pct(answered,n)}% das chamadas`)+kpi('TMA',time(d.callTma),'Duração média das atendidas')+kpi('TME',time(d.callTme),'Espera média das atendidas'):kpi('Chats recebidos',n,'Uma conversa por oportunidade')+kpi('Respondidos',answered,`${n-answered} sem resposta no cenário`)+kpi('TMA',time(d.tma),'Tempo ativo por chat respondido')+kpi('Primeira resposta',time(d.tme),'Espera média nos chats respondidos')}</div><div class="rp-grid"><article class="rp-card"><div class="rp-card-head"><h3>${calls?'CSAT · satisfação':'SLA · primeira resposta'}</h3><span>${calls?'Meta ilustrativa ≥ 90%':'Meta ilustrativa ≥ 80%'}</span></div><div class="rp-gauge-row"><div class="rp-ring" style="--value:${calls?csat:sla};--ring:${(calls?csat:sla)>=(calls?90:80)?'#239d85':'#d59a38'}"><div><strong>${calls?csat:sla}%</strong><span>${calls?'satisfeitos':'dentro de 2 min'}</span></div></div><div><b>${calls?`${d.satisfied} de ${d.surveys.length} avaliações`:`${d.sla} de ${d.chats.length} chats respondidos`}</b><p>${calls?'Notas 4 e 5 em uma escala de 1 a 5. Não respondentes não entram no cálculo.':'Prazo entre a entrada e a primeira resposta. Chats sem resposta são exibidos separadamente.'}</p></div></div></article><article class="rp-card"><div class="rp-card-head"><h3>${calls?'NPS · recomendação':'Distribuição do atendimento'}</h3><span>${calls?'Escala de −100 a +100':'Chats respondidos'}</span></div>${calls?`<div class="rp-nps"><strong>${nps>0?'+':''}${nps}</strong><span>pontos · ${d.surveys.length} respostas</span></div>${bars([['Promotores · 9–10',d.promoters,'#239d85'],['Neutros · 7–8',d.passives,'#9da9bd'],['Detratores · 0–6',d.detractors,'#d78668']])}<p class="rp-note">NPS = % promotores − % detratores. Base pequena e fictícia; não representa satisfação real.</p>`:bars([['Com participação humana',d.chats.filter(r=>r.human).length,'#6264d8'],['Somente IA',d.chats.filter(r=>!r.human).length,'#239d85']])+`<p class="rp-note">Categorias exclusivas. Transferências são parte dos atendimentos com participação humana.</p>`}</article><article class="rp-card"><h3>${calls?'Situação das chamadas':'Situação das conversas'}</h3>${calls?bars([['Atendidas',answered,'#239d85'],['Abandonadas na espera',d.calls.filter(r=>r.abandoned).length,'#d59a38'],['Não atendidas',d.calls.filter(r=>!r.callAnswered&&!r.abandoned).length,'#9da9bd']]):bars([['Encerradas',d.rows.filter(r=>r.closed).length,'#239d85'],['Em andamento',d.rows.filter(r=>!r.closed&&r.answered).length,'#6264d8'],['Aguardando resposta',d.rows.filter(r=>!r.answered).length,'#d59a38']])}<p class="rp-note">${calls?'Abandono: cliente encerrou antes de ser atendido. Não atendida: chamada sem conexão com a equipe.':`${d.rows.filter(r=>r.transferred).length} conversas foram transferidas ao humano; esse total se sobrepõe aos estados acima.`}</p></article><article class="rp-card"><h3>${calls?'Participação nas pesquisas':'Volume por responsável'}</h3>${calls?`<div class="rp-survey"><strong>${pct(d.surveys.length,d.answered.length)}%</strong><span>taxa de resposta</span></div>${bars([['Convites enviados',d.answered.length,'#6264d8'],['Pesquisas respondidas',d.surveys.length,'#239d85'],['Sem avaliação',d.answered.length-d.surveys.length,'#9da9bd']])}<p class="rp-note">Um convite por chamada atendida. Neste cenário, NPS e CSAT usam as mesmas respostas.</p>`:bars(people.filter(p=>person==='all'||p===person).map(p=>[p,d.rows.filter(r=>r.person===p).length]))+`<p class="rp-note">Distribuição fictícia da carteira; volume sozinho não mede qualidade do atendimento.</p>`}</article></div><article class="rp-card rp-table"><div class="rp-card-head"><h3>Comparativo da equipe fictícia</h3><span>Mesmo período e filtro</span></div><div class="rp-table-scroll"><table><thead><tr><th>Pessoa</th><th>${calls?'Chamadas':'Chats'}</th><th>${calls?'Atendidas':'Respondidos'}</th><th>TMA</th><th>${calls?'CSAT':'SLA ≤ 2 min'}</th>${calls?'<th>NPS</th>':''}</tr></thead><tbody>${people.filter(p=>person==='all'||p===person).map(p=>{const a=reportData(days,p);return `<tr><td>${p}</td><td>${calls?a.calls.length:a.rows.length}</td><td>${calls?a.answered.length:a.chats.length}</td><td>${time(calls?a.callTma:a.tma)}</td><td>${pct(calls?a.satisfied:a.sla,calls?a.surveys.length:a.chats.length)}%</td>${calls?`<td>${Math.round((a.promoters-a.detractors)/Math.max(1,a.surveys.length)*100)}</td>`:''}</tr>`}).join('')}</tbody></table></div></article><details class="rp-definitions"><summary>Como ler estes indicadores</summary><p><b>SLA:</b> percentual de chats respondidos em até 2 minutos. <b>TMA:</b> tempo médio de atendimento ativo; não é o tempo total desde a abertura. <b>TME:</b> espera média antes do atendimento. <b>CSAT:</b> avaliações 4 ou 5 divididas pelas avaliações recebidas. <b>NPS:</b> percentual de notas 9–10 menos percentual de notas 0–6.</p><p>Recorte fixo e dados locais para apresentação. Alterar filtros apenas recalcula esses exemplos. A Visão geral do CRM continua sendo o painel conectado à operação.</p></details></section>`;
 root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;draw()});root.querySelector('#rp-days').onchange=e=>{days=+e.target.value;draw()};root.querySelector('#rp-person').onchange=e=>{person=e.target.value;draw()};
 }draw();}
